<?php require_once __DIR__.'/config/config.php';require_login();if(!is_admin()){http_response_code(403);exit('Admin access only.');}$page_title='Admin Dashboard';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';if($action==='delete_post'&&$id){$s=$conn->prepare('DELETE FROM posts WHERE id=?');$s->bind_param('i',$id);$s->execute();flash('Post removed.');}elseif($action==='delete_user'&&$id!==current_user_id()){$s=$conn->prepare("DELETE FROM users WHERE id=? AND role<>'admin'");$s->bind_param('i',$id);$s->execute();flash('Member removed.');}elseif($action==='review_report'&&$id){$s=$conn->prepare("UPDATE reports SET status='reviewed' WHERE id=?");$s->bind_param('i',$id);$s->execute();flash('Report marked as reviewed.');}redirect('admin.php');}$counts=[];foreach(['users','posts','comments','reports'] as $t)$counts[$t]=(int)$conn->query("SELECT COUNT(*) n FROM `$t`")->fetch_assoc()['n'];$posts=$conn->query('SELECT p.id,p.body,u.username FROM posts p JOIN users u ON u.id=p.user_id ORDER BY p.created_at DESC LIMIT 50');$users=$conn->query('SELECT id,username,email,role FROM users ORDER BY created_at DESC LIMIT 50');$reports=$conn->query("SELECT r.*,p.body,u.username FROM reports r JOIN posts p ON p.id=r.post_id JOIN users u ON u.id=r.reporter_id WHERE r.status='open' ORDER BY r.created_at DESC");require __DIR__.'/includes/header.php';?><div class="page-heading"><p class="eyebrow">COMMUNITY MANAGEMENT</p><h1>Admin Dashboard ♡</h1></div><div class="stats-grid"><?php foreach($counts as $k=>$v):?><div class="card stat-card"><small><?=e(ucfirst($k))?></small><strong><?=$v?></strong></div><?php endforeach;?></div><section class="card admin-section"><h2>Reported posts</h2><?php if(!$reports->num_rows):?><p class="muted">No open reports.</p><?php endif;?><?php while($r=$reports->fetch_assoc()):?><div class="admin-row"><div><b>@<?=e($r['username'])?> reported</b><p><?=e($r['reason'])?></p><small><?=e(mb_strimwidth($r['body'],0,140,'…'))?></small></div><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn btn-light" name="action" value="review_report">Mark reviewed</button><button class="btn danger" name="action" value="delete_post">Delete post</button></form></div><?php endwhile;?></section><section class="card admin-section"><h2>Recent posts</h2><?php while($r=$posts->fetch_assoc()):?><div class="admin-row"><span>@<?=e($r['username'])?> — <?=e(mb_strimwidth($r['body'],0,100,'…'))?></span><form method="post" onsubmit="return confirm('Delete this post?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger" name="action" value="delete_post">Delete</button></form></div><?php endwhile;?></section><section class="card admin-section"><h2>Members</h2><?php while($u=$users->fetch_assoc()):?><div class="admin-row"><span>@<?=e($u['username'])?> · <?=e($u['email'])?> · <?=e($u['role'])?></span><?php if($u['role']!=='admin'):?><form method="post" onsubmit="return confirm('Remove this member?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$u['id']?>"><button class="btn danger" name="action" value="delete_user">Remove</button></form><?php endif;?></div><?php endwhile;?></section><?php require __DIR__.'/includes/footer.php';?>